"""Pydantic schemas for Gemma 4 voucher classification responses."""

from typing import Any, Dict, List, Optional
from pydantic import BaseModel, Field, field_validator

from app.ml.taxonomy import (
    AUTHORITATIVE_VOUCHER_LABELS,
    normalize_voucher_label,
)


class GemmaVoucherPrediction(BaseModel):
    """Structured classification prediction generated by Gemma 4."""

    category: str = Field(
        ...,
        description="The predicted accounting voucher category, strictly matching one of the 27 authoritative labels",
    )
    confidence: float = Field(
        ...,
        ge=0.0,
        le=1.0,
        description="Calibrated confidence score between 0.0 and 1.0",
    )
    alternative_category: Optional[str] = Field(
        default=None,
        description="Secondary plausible voucher category if ambiguity exists",
    )
    alternative_confidence: Optional[float] = Field(
        default=None,
        ge=0.0,
        le=1.0,
        description="Confidence score for the secondary candidate",
    )
    reasoning: str = Field(
        ...,
        description="Concise, audit-grade explanation of the classification decision based on transaction fields",
    )
    detected_signals: List[str] = Field(
        default_factory=list,
        description="Key financial and entity signals identified in the record (e.g. 'goods receipt note', 'vendor payment')",
    )
    review_recommended: bool = Field(
        default=False,
        description="Flag indicating human auditor review is recommended due to ambiguity or low confidence",
    )

    @field_validator("category")
    @classmethod
    def validate_category(cls, v: str) -> str:
        norm = normalize_voucher_label(v)
        if not norm:
            raise ValueError(
                f"Invalid voucher category '{v}'. Must match one of the 27 authoritative labels: {AUTHORITATIVE_VOUCHER_LABELS}"
            )
        return norm

    @field_validator("alternative_category")
    @classmethod
    def validate_alt_category(cls, v: Optional[str]) -> Optional[str]:
        if v is None:
            return None
        norm = normalize_voucher_label(v)
        return norm or v


class GemmaClassificationResult(BaseModel):
    """Full inference result container including runtime metadata and audit flags."""

    row_id: int = Field(..., description="Stable 1-indexed row number from the input dataset")
    prediction: GemmaVoucherPrediction = Field(..., description="The structured voucher prediction")
    model_name: str = Field(..., description="Identifier of the model used (e.g. 'gemma-4-26b-a4b-it' or 'mock-gemma-4-adapter')")
    latency_ms: float = Field(..., description="Inference latency in milliseconds")
    is_mock: bool = Field(..., description="True if output was generated by the deterministic mock adapter; False if verified live Gemini API")
    prompt_tokens: Optional[int] = Field(default=None, description="Number of prompt tokens consumed if reported by provider")
    completion_tokens: Optional[int] = Field(default=None, description="Number of output tokens generated if reported by provider")
    raw_model_output: Optional[str] = Field(default=None, description="Raw model text payload before JSON parsing")
